import{c as l,Q as e,j as o,m as r}from"./chunks/framework.DOi4mjdC.js";const p="/assets/new_1911%E7%B4%A7%E8%80%A6%E5%90%88.J49MCjXJ.png",a="/assets/0707_Fixpipe.D8VcL3sV.png",u="/assets/Fixpipe_int8-channel_merge.CPrebIX1.png",i="/assets/Fixpipe_int4_channel_merge.Bmc8OS0u.png",g="/assets/Fixpipe_F32_channel_split.DwQVcY5_.png",n="/assets/0000000-%E6%A0%B8%E5%86%85%E5%90%8C%E6%AD%A5%E6%9C%80%E7%BB%88%E7%89%88.DNZ8FLgV.png",b=JSON.parse('{"title":"NPU架构版本3002","description":"","frontmatter":{},"headers":[{"level":1,"title":"NPU架构版本3002","slug":"npu架构版本3002"},{"level":2,"title":"硬件架构图","slug":"硬件架构图"},{"level":2,"title":"计算单元","slug":"计算单元"},{"level":2,"title":"存储单元","slug":"存储单元"},{"level":2,"title":"搬运单元","slug":"搬运单元"},{"level":2,"title":"同步控制","slug":"同步控制"}],"relativePath":"guide/编程指南/高级编程/硬件实现/架构规格/NPU架构版本3002.md","filePath":"guide/编程指南/高级编程/硬件实现/架构规格/NPU架构版本3002.md"}'),s={name:"guide/编程指南/高级编程/硬件实现/架构规格/NPU架构版本3002.md"};function d(c,t,q,f,h,B){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="npu架构版本3002" tabindex="-1">NPU架构版本3002 <a class="header-anchor" href="#npu架构版本3002" aria-label="Permalink to &quot;NPU架构版本3002&quot;">​</a></h1><p>本节介绍__NPU_ARCH__版本号为3002的硬件架构和其功能说明。对应的产品型号为：</p><ul><li>Atlas 200I/500 A2 推理产品</li></ul><h2 id="硬件架构图" tabindex="-1">硬件架构图 <a class="header-anchor" href="#硬件架构图" aria-label="Permalink to &quot;硬件架构图&quot;">​</a></h2><p><img src="'+p+'" alt=""></p><h2 id="计算单元" tabindex="-1">计算单元 <a class="header-anchor" href="#计算单元" aria-label="Permalink to &quot;计算单元&quot;">​</a></h2><p><strong>Cube计算单元和Vector计算单元同核部署</strong></p><p>本架构中，Cube计算单元和Vector计算单元同核部署，共享同一个Scalar计算单元。</p><p><strong>Vector计算单元</strong></p><ul><li>Vector计算单元的数据来源来自于Unified Buffer，要求32字节对齐。</li></ul><p><strong>Cube计算单元</strong></p><ul><li>Cube计算单元可以访问的存储单元有L0A Buffer、L0B Buffer、L0C Buffer，其中L0A Buffer存储左矩阵，L0B Buffer存储右矩阵，L0C Buffer存储矩阵乘的结果和中间结果。</li></ul><h2 id="存储单元" tabindex="-1">存储单元 <a class="header-anchor" href="#存储单元" aria-label="Permalink to &quot;存储单元&quot;">​</a></h2><p><strong>获取存储单元的内存空间大小</strong></p><p>开发者可以通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/%E5%B9%B3%E5%8F%B0%E4%BF%A1%E6%81%AF%E8%8E%B7%E5%8F%96.md" target="_blank" rel="noreferrer">平台信息获取</a>接口查询各存储单元的内存空间大小。</p><p><strong>各存储单元的最小访问粒度（对齐要求）</strong></p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;7.5200000000000005%&quot;&gt;&lt;p&gt;核&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.22%&quot;&gt;&lt;p&gt;存储单元&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.26%&quot;&gt;&lt;p&gt;对齐要求&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;7.5200000000000005%&quot;&gt;&lt;p&gt;AIV&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.22%&quot;&gt;&lt;p&gt;&lt;span&gt;Unified Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.26%&quot;&gt;&lt;p&gt;32Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; rowspan=&quot;6&quot; valign=&quot;top&quot; width=&quot;7.5200000000000005%&quot;&gt;&lt;p&gt;AIC&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.22%&quot;&gt;&lt;p&gt;&lt;span&gt;L1 Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;46.26%&quot;&gt;&lt;p&gt;32Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;span&gt;L0A Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;512Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;span&gt;L0B Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;512Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;&lt;span&gt;L0C Buffer&lt;/span&gt;&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;64Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;BiasTable Buffer&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;64Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;Fixpipe Buffer&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot;&gt;&lt;p&gt;64Byte对齐。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p><strong>各存储单元推荐使用的数据排布格式</strong></p><ul><li><p>L0A Buffer、L0B Buffer和L0C Buffer推荐分别采用以下分形格式：</p><ul><li>L0A Buffer：FRACTAL_ZZ</li><li>L0B Buffer：FRACTAL_ZN</li><li>L0C Buffer：FRACTAL_NZ</li></ul><p>这些格式针对矩阵乘法等计算密集型任务进行优化，可显著提升计算效率。</p></li><li><p>L1 Buffer缓存推荐使用FRACTAL_NZ格式。当L1 Buffer采用NZ格式时，数据搬运到L0A/L0B Buffer（需分别转换为ZZ和ZN格式）时，可降低格式转换开销。</p></li><li><p>Unified Buffer对数据格式没有要求。</p></li></ul><p><strong>解决存储单元的访问冲突，提升读写性能</strong></p><p>当多个操作尝试同时访问Unified Buffer同一个bank或者bank group时，可能会发生bank冲突，包括读写冲突、写写冲突、读读冲突，这种冲突会导致访问排队，降低性能。可以通过优化bank分配的方式来提升读写性能，具体信息请参考<a href="./../../../../算子实践参考/SIMD算子性能优化/内存访问/避免UB的bank冲突/避免UB的bank冲突.html">避免UB的bank冲突</a>章节。</p><h2 id="搬运单元" tabindex="-1">搬运单元 <a class="header-anchor" href="#搬运单元" aria-label="Permalink to &quot;搬运单元&quot;">​</a></h2><p><strong>搬运时的对齐要求</strong></p><p>由于搬运后的数据用于参与数据计算，因此对搬运数据大小有要求，搬运到Unified Buffer的数据大小需要按照DataBlock对齐，其余存储单元的数据搬运必须按<a href="./../../../../技术附录/概念原理和术语/神经网络和算子/数据排布格式.html">分形要求</a>进行搬运。例如，数据从L1 Buffer搬运到L0A Buffer时，数据格式需要从NZ转换为ZZ格式，搬运数据的大小要按分形大小对齐，如果L1 Buffer的剩余大小不足1个分形，则硬件执行中会出现异常。</p><p><strong>支持Fixpipe硬件化加速</strong></p><p>Fixpipe是NPU将典型操作进行硬化的加速模块，位于AIC内部，配合Cube计算单元完成随路计算，主要功能如下：</p><ul><li>量化反量化：包括S322FP16、S322S32、S322S4、S322S8、S322S16、FP322FP16、FP322BF16、FP322S8、FP322S4、FP322FP32。</li><li>Relu功能，包括ReLu、PReLu和Leaky ReLu等典型的激活函数。</li><li>数据格式转换，包括： <ul><li>通过Channel merge、Channel split可以实现分形大小的转换，保证输出到L1 Buffer/GM的分形满足诉求。</li><li>NZ2ND数据格式转换。</li></ul></li></ul><p><img src="'+a+'" alt=""></p><p>上图中，Channel merge支持S8、U8、S4和U4数据类型，而Channel split支持FP32数据类型。</p><ul><li><p>Channel merge（S8和U8数据类型）</p><p>对于转换为S8或U8的目标数据类型，分形矩阵通过硬件从16x16转换为16x32，如果输出通道数N是16的偶数倍，则N方向上每2个相邻的16x16分形矩阵将合并为1个16x32分形矩阵。如果N是16的奇数倍，则将通道1到通道（N–16）合并，最后16个通道保持未合并。</p><p>如下所示，目标数据类型为S8，M为32，N为48，首先将前2列16x16分形矩阵合并为一个16x32矩阵，然后将剩余的16x16分形矩阵直接移入L1 Buffer。</p><p><img src="'+u+'" alt=""></p></li><li><p>Channel merge（S4和U4数据类型）</p><p>对于转换为S4或U4的目标数据类型，分形矩阵通过硬件从16x16转换为16x64，如果输出通道数N是64的倍数，则N方向上每4个相邻的16x16分形矩阵将合并为1个16x64分形矩阵。</p><p>例如，这里目标数据类型为S4，M为32，N为64，首先将第1行16x16分形矩阵合并为一个16x64矩阵，然后将第2行16x16分形矩阵也合并。</p><p>在这种情况下，N的配置必须是64的倍数。</p><p><img src="'+i+'" alt=""></p></li><li><p>FP32 Channel split：</p><p>对于目标类型为FP32，分形矩阵可以通过硬件从16x16转换为16x8，如果使能Channel split，则每个16x16分形矩阵将被分裂为2个16x8分形矩阵。</p><p>如下图所示，这里的目标数据类型是FP32，M是64，N是32，它将被拆分为16个16x8的分形。</p><p><img src="'+g+'" alt=""></p></li></ul><h2 id="同步控制" tabindex="-1">同步控制 <a class="header-anchor" href="#同步控制" aria-label="Permalink to &quot;同步控制&quot;">​</a></h2><ul><li><p>核内同步</p><p>由于AI Core内部的执行单元（如MTE2搬运单元、Vector计算单元等）以异步并行的方式运行，在读写Local Memory（如Unified Buffer）时可能存在数据依赖关系。为确保数据一致性及计算正确性，需通过同步控制协调操作时序。</p><p>以MTE2从GM搬运数据至UB，进行Vector计算单元的Abs计算，再搬运回GM的流程为例，需满足以下同步条件：</p><ol><li><p>数据搬运与计算顺序</p><ul><li>GM→UB搬运完成后再启动Vector单元的Abs计算（避免计算时未完成搬运导致的数据缺失）；</li><li>Vector计算完成后再执行UB→GM的数据搬运（确保结果数据已就绪）。</li></ul></li><li><p>循环搬运计算场景的同步规则</p><ul><li>前序计算完成后再启动新搬运：上一次计算未完成时，不得触发新数据搬运（防止UB中旧数据被覆盖）；</li><li>前序数据搬出完成后再启动新计算：上一次数据未完全从UB搬出时，不得触发新计算任务（避免目标内存区域的覆盖冲突）。</li></ul></li></ol><p>同步控制流程如下图所示：</p><p><img src="'+n+'" alt=""></p><p>上图中，ID1、ID2、ID3、ID4、ID5、ID6表示事件ID（EventID），每个EventID对应一块存储数据的搬运状态，确保数据操作的正确性和一致性。</p><p>需要注意以下几点：</p><ul><li><p>建议通过<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/AllocEventID.md" target="_blank" rel="noreferrer">AllocEventID</a>或者<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FetchEventID.md" target="_blank" rel="noreferrer">FetchEventID</a>接口获取EventID，以确保其合法性和有效性。</p></li><li><p>EventID的数量有限，使用后应立即调用ReleaseEventID释放资源，避免EventID耗尽，影响系统正常运行。</p></li><li><p>SetFlag和WaitFlag必须成对使用，且SetFlag和WaitFlag的参数必须完全一致（包括模板参数和事件ID）。如果不匹配，可能导致当前核的计算异常，或影响下一个核的算子执行，引发timeout问题。</p><p>例如，<code>SetFlag&lt;HardEvent::S_MTE3&gt;(1)</code>和<code>SetFlag&lt;HardEvent::MTE3_MTE1&gt;(1)</code>设置的不是同一个EventID，因为其模板参数不同。只有当模板参数和事件ID完全一致时，才表示同一个EventID。</p></li><li><p>不允许连续设置同一个EventID，因为这可能导致事件状态混乱或未被正确处理。</p></li><li><p>不建议手动插入 TEventID，不能手动插入6和7的TEventID，因为它们可能被系统预留或用于特殊用途。</p></li></ul></li><li><p>核间同步</p><p>该硬件架构不支持核间同步。</p></li></ul>',32)])])}const m=l(s,[["render",d]]);export{b as __pageData,m as default};
